  const links = Array.from(document.querySelectorAll("a[href*='/p/'], a[href*='gift-set'], [class*='product_name'] a, [class*='ProductCard'] a"));
  const seen = new Set();
  const items = [];

  for (const a of links) {
    const title = a.innerText.trim();
    if (!title || seen.has(title) || title.length < 5) continue;
    seen.add(title);

    // Find closest container that has price
    let parent = a.closest("li, div[class*='product'], div[class*='card'], article");
    if (!parent) parent = a.parentElement?.parentElement;
    const text = parent ? parent.innerText : "";
    const price = text.match(/£\d+(\.\d{2})?/)?.[0];
    items.push({
      title,
      price,
      href: a.href,
      summary: text.replace(/\n+/g, " | ").slice(0, 150)
    });
  }
  return {
    pageTitle: document.title,
    count: items.length,
    items: items.slice(0, 15)
  };
});

