const tabId = 103795354;

const items = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll("div.product_card, [class*='ProductCard'], [id*='product_tile'], li[class*='grid_item']"));

  // If specific selectors didn't match, let's find elements that have an anchor and a price
  const results = [];
  const anchors = Array.from(document.querySelectorAll("a"))
    .filter(a => a.href && a.href.includes("/p/") && a.innerText.length > 5);

  for (const a of anchors) {
    const parent = a.closest("li, div[class*='product'], div[class*='item']") || a.parentElement?.parentElement;
    const text = parent ? parent.innerText : a.innerText;
    const priceMatch = text.match(/£\d+(\.\d{2})?/);
    results.push({
      name: a.innerText.trim(),
      link: a.href,
      price: priceMatch ? priceMatch[0] : null,
      fullText: text.replace(/\n+/g, " | ").slice(0, 200)
    });
  }
  return results;
});

console.log("Boots parsed items count:", items.length);
console.log("Boots items sample:", JSON.stringify(items.slice(0, 25), null, 2));

