    if (text.toLowerCase().includes("gift set") || text.toLowerCase().includes("aftershave") || text.toLowerCase().includes("fragrance") || text.toLowerCase().includes("lynx") || text.toLowerCase().includes("eau de")) {
      const parent = h.closest("li, div[class*='product'], div[class*='card'], article") || h.parentElement;
      const fullText = parent ? parent.innerText : text;
      const price = fullText.match(/£\d+(\.\d{2})?/)?.[0];
      const link = h.tagName === "A" ? h.href : h.querySelector("a")?.href || parent?.querySelector("a")?.href;
      matched.push({
        title: text,
        price,
        link,
        context: fullText.replace(/\s+/g, " ").slice(0, 150)
      });
    }
  }
  return matched;
});

